  "twofa.enabled": "\u0414\u0432\u0443\u0445\u0444\u0430\u043a\u0442\u043e\u0440\u043d\u0430\u044f \u0430\u0443\u0442\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0430",
  "twofa.disabled": "\u0414\u0432\u0443\u0445\u0444\u0430\u043a\u0442\u043e\u0440\u043d\u0430\u044f \u0430\u0443\u0442\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430",
  "twofa.codesTitle": "\u041a\u043e\u0434\u044b \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u2014 \u0432\u0438\u0434\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0435\u0439\u0447\u0430\u0441",
  "twofa.codesHint": "\u0415\u0441\u043b\u0438 \u043f\u043e\u0442\u0435\u0440\u044f\u0435\u0442\u0435 \u0442\u0435\u043b\u0435\u0444\u043e\u043d, \u0432\u043e\u0439\u0434\u0451\u0442\u0435 \u043f\u043e \u044d\u0442\u0438\u043c \u043a\u043e\u0434\u0430\u043c. \u041a\u0430\u0436\u0434\u044b\u0439 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043e\u0434\u0438\u043d \u0440\u0430\u0437. \u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435 \u043a\u043e\u043f\u0438\u044e.",
  "twofa.codesSaved": "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u043b",
  "twofa.recoveryLeft": "\u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c \u043a\u043e\u0434\u043e\u0432",
  "twofa.recoveryLeftHint": "\u0415\u0441\u043b\u0438 \u0437\u0430\u043a\u043e\u043d\u0447\u0430\u0442\u0441\u044f \u2014 \u043e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0438 \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u0435 2FA \u0437\u0430\u043d\u043e\u0432\u043e",
  "twofa.regenTitle": "\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u043a\u043e\u0434\u044b \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f",
  "twofa.regenHint": "\u0415\u0441\u043b\u0438 \u0435\u0441\u0442\u044c \u043f\u043e\u0434\u043e\u0437\u0440\u0435\u043d\u0438\u0435, \u0447\u0442\u043e \u043a\u043e\u0434\u044b \u0443\u0432\u0438\u0434\u0435\u043b \u043f\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439 \u2014 \u043e\u0431\u043d\u043e\u0432\u0438\u0442\u0435 \u0438\u0445 \u0437\u0434\u0435\u0441\u044c. \u0421\u0442\u0430\u0440\u044b\u0435 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u0443\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0441\u0440\u0430\u0437\u0443, \u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c.",
  "twofa.regen": "\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c",
  "twofa.regenWarn": "\u0412\u0441\u0435 \u0441\u0442\u0430\u0440\u044b\u0435 \u043a\u043e\u0434\u044b \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0431\u0443\u0434\u0443\u0442 \u0430\u043d\u043d\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0431\u0435\u0437\u0432\u043e\u0437\u0432\u0440\u0430\u0442\u043d\u043e. \u0421\u043f\u0438\u0441\u043e\u043a \u043d\u0430 \u0431\u0443\u043c\u0430\u0433\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u043f\u043e\u0434\u043e\u0439\u0434\u0451\u0442. \u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c?",
